import{_ as o,o as t,c as d,ak as a}from"./chunks/framework.D6lxc04_.js";const b=JSON.parse('{"title":"Rendering 渲染","description":"","frontmatter":{"title":"Rendering 渲染","prev":false,"next":false},"headers":[],"relativePath":"posts/docs/rendering/index.md","filePath":"posts/docs/rendering/index.md","lastUpdated":1778064395000}'),r={name:"posts/docs/rendering/index.md"};function i(n,e,c,l,s,h){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="渲染模块" tabindex="-1">渲染模块 <a class="header-anchor" href="#渲染模块" aria-label="Permalink to “渲染模块”">​</a></h1><p>包 <code>dev.anvilcraft.lib.v2.rendering</code> 提供了泛光（Bloom）后处理效果以及一套通用的 UBO（Uniform Buffer Object）布局定义框架，并通过 Mixin 集成到 Minecraft 的 GUI 渲染和主渲染流程中。</p><h2 id="文档索引" tabindex="-1">文档索引 <a class="header-anchor" href="#文档索引" aria-label="Permalink to “文档索引”">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>内容</th></tr></thead><tbody><tr><td><a href="./bloom.html">泛光后处理</a></td><td><code>BloomPostEffect</code>、<code>BloomRenderCallback</code>、多 Pass 处理链</td></tr><tr><td><a href="./ubo.html">UBO 框架</a></td><td><code>UboObject</code>、<code>UboLayoutDefinition</code>、<code>UboLayoutEntry</code>、STD140 布局</td></tr><tr><td><a href="./integration.html">渲染集成</a></td><td><code>ALRendering</code>、Mixin、<code>LibGuiElementRenderState</code>、着色器管线</td></tr></tbody></table><h2 id="模块结构" tabindex="-1">模块结构 <a class="header-anchor" href="#模块结构" aria-label="Permalink to “模块结构”">​</a></h2><ul><li><strong>主类</strong>: <code>ALRendering</code> — 模组入口，创建管线，注册事件</li><li><strong>后处理</strong>: <code>BloomPostEffect</code> — 泛光效果多 Pass 处理链</li><li><strong>UBO 框架</strong>: <code>foundation.ubo</code> 包 — 类型安全的 ST140 布局定义</li><li><strong>着色器</strong>: <code>blit.vsh</code>, <code>blur.fsh</code>, <code>apply_bloom.fsh</code>, <code>down_sample.fsh</code>, <code>up_sample.fsh</code></li><li><strong>Mixin</strong>: <code>GuiRendererMixin</code>, <code>MinecraftMixin</code> — 渲染流程嵌入</li></ul><blockquote><p>该模块仅在 Minecraft 26.1 版本中存在（<code>module.rendering</code>）。</p></blockquote><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to “注意事项”">​</a></h2><ul><li>泛光效果依赖大量 RenderTarget 创建，限定客户端环境</li><li>所有 GPU 资源由 <code>GpuDevice</code> 创建，生命周期跟随 <code>BloomPostEffect</code> 实例</li><li>Mixin 修改 <code>GuiRenderer</code> 内部行为，可能与其它渲染模组冲突</li></ul>',9)])])}const m=o(r,[["render",i]]);export{b as __pageData,m as default};
